import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        System.out.print("Principal ($): ");          double P = sc.nextDouble();
        System.out.print("Annual rate (e.g. 0.05): "); double r = sc.nextDouble();
        System.out.print("Times/year compounded: ");  int    n = sc.nextInt();
        System.out.print("Years: ");                  int    t = sc.nextInt();
        sc.close();

        double A = P * Math.pow(1 + r / n, n * t);
        System.out.printf("Final amount:    $%.2f%n", A);
        System.out.printf("Interest earned: $%.2f%n", A - P);
    }
}

