        sc.close();

        // Conversion formulas on next slide
    }
}

if (unit.equals("C")) {
    double converted = temp * (9.0 / 5.0) + 32;
    System.out.printf("%.1f C = %.1f F%n", temp, converted);
    // 100.0 C = 212.0 F

} else if (unit.equals("F")) {
    double converted = (temp - 32) * (5.0 / 9.0);
    System.out.printf("%.1f F = %.1f C%n", temp, converted);
    // 32.0 F = 0.0 C

} else {
    System.out.println("Enter C or F.");
}

