int days = switch (month) {
    case 1, 3, 5, 7, 8, 10, 12 -> 31;
    case 4, 6, 9, 11           -> 30;
    case 2 -> {
        // Multi-statement block — use yield to return
        boolean isLeap = (year % 400 == 0) ||
                         (year % 4 == 0 && year % 100 != 0);
        yield isLeap ? 29 : 28;
    }
    default -> -1;
};

System.out.println("Days in Feb " + year + ": " + days);  // 29

