    }
}

double result = 0;
boolean valid = true;

switch (op) {
    case "+" -> result = a + b;
    case "-" -> result = a - b;
    case "*" -> result = a * b;
    case "/" -> {
        if (b == 0) {
            System.out.println("Error: cannot divide by zero.");
            valid = false;
        } else { result = a / b; }
    }
    default -> { System.out.println("Unknown operator: " + op); valid = false; }
}

if (valid) {
    System.out.printf("%.2f %s %.2f = %.2f%n", a, op, b, result);
}

// Extended switch — add modulus and power
switch (op) {
    case "+" -> result = a + b;
    case "-" -> result = a - b;
    case "*" -> result = a * b;
    case "/" -> {
        if (b == 0) { System.out.println("Div by zero!"); valid = false; result = 0; }
        else result = a / b;
    }
    case "%" -> result = a % b;
    case "^" -> result = Math.pow(a, b);
    default  -> { System.out.println("Unknown operator."); valid = false; result = 0; }
}

// Challenge: wrap the whole program in while(true) { ... }

int temp        = 22;
boolean isSunny = true;

// Both must be true
if (temp >= 18 && isSunny) {
    System.out.println("Good day for a walk!");  // runs
}

// Range check — both bounds required
int score = 75;
if (score >= 60 && score <= 100) {
    System.out.println("Valid passing score.");   // runs
}

// Short-circuit: temp < 30, so isSunny never evaluated
if (temp >= 30 && isSunny) {
    System.out.println("Hot and sunny.");         // skipped
}

boolean isWeekend = true;
boolean isHoliday = false;

// OR — true if either is true
if (isWeekend || isHoliday) {
    System.out.println("Day off!");  // runs — isWeekend is true
}

// NOT — invert a boolean
boolean isWorking = !isWeekend;
System.out.println("Working: " + isWorking);  // Working: false

// Combined
int age = 17;
boolean hasPermission = false;
if (age >= 18 || hasPermission) {
    System.out.println("Granted.");
} else {
    System.out.println("Denied.");  // runs
}

int age         = 25;
boolean isEmployee = true;
boolean hasBadge   = false;

// Precedence trap: && binds tighter
// Reads as: age>=18 || (isEmployee && hasBadge)
if (age >= 18 || isEmployee && hasBadge) {
    System.out.println("Enters — age>=18 is true");  // runs
}

// Explicit parentheses — different result
if ((age >= 18 || isEmployee) && hasBadge) {
    System.out.println("Secure area");  // skipped — hasBadge is false
}

